BEGIN; SET LOCAL statement_timeout='10s'; SET LOCAL lock_timeout='2s'; SET LOCAL search_path=public,extensions,pg_temp;
DO $$ BEGIN IF session_user<>'fixture_bootstrap' OR current_database() !~ '^qual_spin_expiry_[0-9a-f]{32}$' OR inet_server_addr() IS NOT NULL OR current_setting('listen_addresses')<>'' OR EXISTS(SELECT 1 FROM public.cash_games) THEN RAISE EXCEPTION 'HORSE_EMPTY_CLUSTER_PROVIDER_REQUIRED'; END IF; END $$;
ALTER TABLE public.cash_games ADD COLUMN IF NOT EXISTS cluster_mode text DEFAULT 'must_move'::text NOT NULL;
DO $$ BEGIN IF (SELECT jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'default',pg_get_expr(d.adbin,d.adrelid),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.cash_games'::regclass AND a.attname='cluster_mode') IS DISTINCT FROM '{"name": "cluster_mode", "type": "text", "default": "''must_move''::text", "notnull": true, "identity": "", "generated": ""}'::jsonb THEN RAISE EXCEPTION 'HORSE_CURRENT_CLUSTER_COLUMN_CHANGED'; END IF; END $$;
ALTER TABLE public.cash_games ADD COLUMN IF NOT EXISTS lightning_enabled boolean DEFAULT false NOT NULL;
DO $$ BEGIN IF (SELECT jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'default',pg_get_expr(d.adbin,d.adrelid),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.cash_games'::regclass AND a.attname='lightning_enabled') IS DISTINCT FROM '{"name": "lightning_enabled", "type": "boolean", "default": "false", "notnull": true, "identity": "", "generated": ""}'::jsonb THEN RAISE EXCEPTION 'HORSE_CURRENT_CLUSTER_COLUMN_CHANGED'; END IF; END $$;
ALTER TABLE public.cash_games ADD COLUMN IF NOT EXISTS cluster_epoch integer DEFAULT 0 NOT NULL;
DO $$ BEGIN IF (SELECT jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'default',pg_get_expr(d.adbin,d.adrelid),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.cash_games'::regclass AND a.attname='cluster_epoch') IS DISTINCT FROM '{"name": "cluster_epoch", "type": "integer", "default": "0", "notnull": true, "identity": "", "generated": ""}'::jsonb THEN RAISE EXCEPTION 'HORSE_CURRENT_CLUSTER_COLUMN_CHANGED'; END IF; END $$;
COMMIT;
